window.docContents[115].resolve({"/1___-Introduction/#chapter-01":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory","header":"1. Introduction","id":"/1___-Introduction/#chapter-01"},"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Finite-abelian-category/#Chapter9___Definition9___6___1":{"contents":"Definition 9.6.1. Let us say that \\mathcal{C} is finite if it has enough projectives and finitely many simple objects (up to an isomorphism).\n\nFor example, as we have shown, the category of finite dimensional modules over a finite dimensional algebra is finite. Below we will see that the converse is also true.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.6. Finite abelian categories\tFinite abelian category","header":"Finite abelian category","id":"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Finite-abelian-category/#Chapter9___Definition9___6___1"}});
